package com.saasquatch.intelligence.entity;
import jakarta.persistence.*;
@Entity @Table(name="corporate_relationships") public class CorporateRelationship { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="company_id") private Company company; @ManyToOne(optional=false) @JoinColumn(name="related_company_id") private Company relatedCompany; @Enumerated(EnumType.STRING) private RelationshipType type; private String effectiveDate; @Column(length=500) private String description; public Long getId(){return id;} public Company getCompany(){return company;} public void setCompany(Company v){company=v;} public Company getRelatedCompany(){return relatedCompany;} public void setRelatedCompany(Company v){relatedCompany=v;} public RelationshipType getType(){return type;} public void setType(RelationshipType v){type=v;} public String getEffectiveDate(){return effectiveDate;} public void setEffectiveDate(String v){effectiveDate=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }